ALTER TABLE public.world_members ADD COLUMN land_trade_coins bigint NOT NULL DEFAULT 0;
CREATE TABLE public.tile_requests (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),world_id uuid NOT NULL REFERENCES public.worlds(id) ON DELETE CASCADE,tile_x integer NOT NULL,tile_y integer NOT NULL,requester_id uuid NOT NULL,owner_id uuid NOT NULL,kind text NOT NULL CHECK(kind IN('offer','contest')),amount bigint,status text NOT NULL DEFAULT 'pending' CHECK(status IN('pending','countered','accepted','rejected','conflict','expired','cancelled')),created_at timestamptz NOT NULL DEFAULT now(),deadline_game_hour double precision);
GRANT SELECT ON public.tile_requests TO authenticated;
GRANT ALL ON public.tile_requests TO service_role;
ALTER TABLE public.tile_requests ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Participants can read tile requests" ON public.tile_requests FOR SELECT TO authenticated USING(public.is_world_member(auth.uid(),world_id) AND auth.uid() IN(requester_id,owner_id));
CREATE UNIQUE INDEX tile_requests_active_tile ON public.tile_requests(world_id,tile_x,tile_y) WHERE status IN('pending','countered','conflict');
CREATE INDEX tile_requests_due ON public.tile_requests(world_id,deadline_game_hour) WHERE kind='contest' AND status='pending';
CREATE FUNCTION public.tile_land_value(_world uuid,_x integer,_y integer) RETURNS bigint LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ DECLARE t jsonb; base bigint; BEGIN SELECT map_data->'tiles'->_y->_x INTO t FROM worlds WHERE id=_world; IF t IS NULL THEN RAISE EXCEPTION 'Tile not found'; END IF; base:=CASE t->>'type' WHEN 'grass' THEN 5 WHEN 'forest' THEN 10 WHEN 'jungle' THEN 15 WHEN 'dirt' THEN 3 WHEN 'sand' THEN 4 WHEN 'water' THEN 12 WHEN 'mountain' THEN 20 WHEN 'stone' THEN 8 WHEN 'snow' THEN 6 WHEN 'ice' THEN 7 WHEN 'lava' THEN 50 WHEN 'swamp' THEN 8 ELSE 5 END; RETURN base+COALESCE((SELECT sum(r.base_value) FROM jsonb_array_elements_text(COALESCE(t->'resources','[]')) a(resource_id) JOIN resource_marketplace r ON r.id::text=a.resource_id),0); END $$;
CREATE FUNCTION public.preserve_negotiated_ownership() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE r record; BEGIN FOR r IN SELECT DISTINCT ON(tile_x,tile_y) tile_x,tile_y,requester_id FROM tile_requests WHERE world_id=NEW.id AND status IN('accepted','expired') ORDER BY tile_x,tile_y,created_at DESC LOOP IF NEW.map_data->'tiles'->r.tile_y->r.tile_x IS NOT NULL THEN NEW.map_data:=jsonb_set(NEW.map_data,ARRAY['tiles',r.tile_y::text,r.tile_x::text,'claimedBy'],to_jsonb(r.requester_id::text)); END IF; END LOOP; RETURN NEW; END $$;
CREATE TRIGGER preserve_negotiated_ownership BEFORE UPDATE OF map_data ON public.worlds FOR EACH ROW EXECUTE FUNCTION public.preserve_negotiated_ownership();
CREATE FUNCTION public.resolve_tile_contests(_world uuid DEFAULT NULL) RETURNS integer LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE r record; w worlds%ROWTYPE; n integer:=0; BEGIN IF auth.uid() IS NOT NULL AND(_world IS NULL OR NOT is_world_member(auth.uid(),_world)) THEN RAISE EXCEPTION 'Not a world member'; END IF; FOR w IN SELECT * FROM worlds WHERE(_world IS NULL OR id=_world) AND EXISTS(SELECT 1 FROM tile_requests r WHERE r.world_id=worlds.id AND r.kind='contest' AND r.status='pending' AND r.deadline_game_hour<=extract(epoch FROM(now()-worlds.created_at))/3600*24) ORDER BY id FOR UPDATE LOOP FOR r IN SELECT * FROM tile_requests WHERE world_id=w.id AND kind='contest' AND status='pending' AND deadline_game_hour<=extract(epoch FROM(now()-w.created_at))/3600*24 FOR UPDATE LOOP IF w.map_data->'tiles'->r.tile_y->r.tile_x->>'claimedBy'=r.owner_id::text AND is_world_member(r.requester_id,w.id) THEN UPDATE tile_requests SET status='expired' WHERE id=r.id; UPDATE worlds SET map_data=jsonb_set(map_data,ARRAY['tiles',r.tile_y::text,r.tile_x::text,'claimedBy'],to_jsonb(r.requester_id::text)) WHERE id=w.id; n:=n+1; ELSE UPDATE tile_requests SET status='cancelled' WHERE id=r.id; END IF; END LOOP; END LOOP; RETURN n; END $$;
CREATE FUNCTION public.create_tile_request(_world uuid,_x integer,_y integer,_kind text,_amount bigint DEFAULT NULL) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE w worlds%ROWTYPE; owner uuid; result uuid; value bigint; balance bigint; BEGIN IF auth.uid() IS NULL OR NOT is_world_member(auth.uid(),_world) THEN RAISE EXCEPTION 'Not a world member'; END IF; PERFORM resolve_tile_contests(_world); SELECT * INTO w FROM worlds WHERE id=_world FOR UPDATE; IF _x<0 OR _y<0 OR _x>=(w.map_data->>'width')::integer OR _y>=(w.map_data->>'height')::integer THEN RAISE EXCEPTION 'Tile not found'; END IF; BEGIN owner:=(w.map_data->'tiles'->_y->_x->>'claimedBy')::uuid; EXCEPTION WHEN invalid_text_representation THEN RAISE EXCEPTION 'Only player-owned tiles can receive requests'; END; IF owner IS NULL OR owner=auth.uid() OR NOT is_world_member(owner,_world) THEN RAISE EXCEPTION 'Choose another player''s tile'; END IF; IF _kind NOT IN('offer','contest') THEN RAISE EXCEPTION 'Invalid request'; END IF; IF _kind='offer' THEN value:=tile_land_value(_world,_x,_y); IF _amount IS NULL OR _amount<value THEN RAISE EXCEPTION 'Minimum offer is % coins',value; END IF; SELECT COALESCE((player_data->>'coins')::bigint,500)+land_trade_coins INTO balance FROM world_members WHERE world_id=_world AND user_id=auth.uid(); IF balance<_amount THEN RAISE EXCEPTION 'Not enough coins'; END IF; END IF; INSERT INTO tile_requests(world_id,tile_x,tile_y,requester_id,owner_id,kind,amount,deadline_game_hour) VALUES(_world,_x,_y,auth.uid(),owner,_kind,CASE WHEN _kind='offer' THEN _amount END,CASE WHEN _kind='contest' THEN extract(epoch FROM(now()-w.created_at))/3600*24+24 END) RETURNING id INTO result; RETURN result; END $$;
CREATE FUNCTION public.respond_tile_request(_id uuid,_action text,_amount bigint DEFAULT NULL) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE r tile_requests%ROWTYPE; w worlds%ROWTYPE; wid uuid; balance bigint; BEGIN SELECT world_id INTO wid FROM tile_requests WHERE id=_id; IF auth.uid() IS NULL OR wid IS NULL OR NOT is_world_member(auth.uid(),wid) THEN RAISE EXCEPTION 'Request not found'; END IF; PERFORM resolve_tile_contests(wid); SELECT * INTO w FROM worlds WHERE id=wid FOR UPDATE; SELECT * INTO r FROM tile_requests WHERE id=_id FOR UPDATE; IF r.status NOT IN('pending','countered') THEN RAISE EXCEPTION 'Request is already resolved'; END IF; IF(r.status='pending' AND auth.uid()<>r.owner_id) OR(r.status='countered' AND auth.uid()<>r.requester_id) THEN RAISE EXCEPTION 'Only the recipient can respond'; END IF; IF w.map_data->'tiles'->r.tile_y->r.tile_x->>'claimedBy' IS DISTINCT FROM r.owner_id::text THEN RAISE EXCEPTION 'Tile ownership has changed'; END IF; IF _action='reject' AND r.kind='offer' THEN UPDATE tile_requests SET status='rejected' WHERE id=_id; RETURN; END IF; IF _action='counter' AND r.kind='offer' AND r.status='pending' THEN IF _amount IS NULL OR _amount<tile_land_value(wid,r.tile_x,r.tile_y) THEN RAISE EXCEPTION 'Counteroffer must meet land value'; END IF; UPDATE tile_requests SET status='countered',amount=_amount WHERE id=_id; RETURN; END IF; IF _action='conflict' AND r.kind='contest' THEN UPDATE tile_requests SET status='conflict' WHERE id=_id; RETURN; END IF; IF NOT((_action='approve' AND r.kind='offer') OR(_action='give_up' AND r.kind='contest')) THEN RAISE EXCEPTION 'Invalid response'; END IF; IF r.kind='offer' THEN PERFORM id FROM world_members WHERE world_id=wid AND user_id IN(r.requester_id,r.owner_id) ORDER BY user_id FOR UPDATE; SELECT COALESCE((player_data->>'coins')::bigint,500)+land_trade_coins INTO balance FROM world_members WHERE world_id=wid AND user_id=r.requester_id; IF balance IS NULL OR balance<r.amount THEN RAISE EXCEPTION 'Buyer does not have enough coins'; END IF; UPDATE world_members SET land_trade_coins=land_trade_coins-r.amount WHERE world_id=wid AND user_id=r.requester_id; UPDATE world_members SET land_trade_coins=land_trade_coins+r.amount WHERE world_id=wid AND user_id=r.owner_id; END IF; UPDATE tile_requests SET status='accepted' WHERE id=_id; UPDATE worlds SET map_data=jsonb_set(map_data,ARRAY['tiles',r.tile_y::text,r.tile_x::text,'claimedBy'],to_jsonb(r.requester_id::text)) WHERE id=wid; END $$;
REVOKE ALL ON FUNCTION public.tile_land_value(uuid,integer,integer),public.preserve_negotiated_ownership(),public.resolve_tile_contests(uuid),public.create_tile_request(uuid,integer,integer,text,bigint),public.respond_tile_request(uuid,text,bigint) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.resolve_tile_contests(uuid),public.create_tile_request(uuid,integer,integer,text,bigint),public.respond_tile_request(uuid,text,bigint) TO authenticated,service_role;
CREATE FUNCTION public.protect_land_trade_coins() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF current_user IN('authenticated','anon') AND NEW.land_trade_coins IS DISTINCT FROM OLD.land_trade_coins THEN RAISE EXCEPTION 'Trade coins are managed by tile transactions'; END IF; RETURN NEW; END $$;
CREATE TRIGGER protect_land_trade_coins BEFORE UPDATE ON public.world_members FOR EACH ROW EXECUTE FUNCTION public.protect_land_trade_coins();
CREATE EXTENSION IF NOT EXISTS pg_cron;